module tb;
    reg [5:0] y;
    reg       w;
    wire      Y1;
    wire      Y3;

    TopModule dut (
        .y(y),
        .w(w),
        .Y1(Y1),
        .Y3(Y3)
    );

    integer errors = 0;
    reg [5:0] expected_Y1_vec;
    reg [5:0] expected_Y3_vec;
    integer i, j;

    initial begin
        // Test all valid one-hot states and various w values
        // States:
        // y[0] = A (000001)
        // y[1] = B (000010)
        // y[2] = C (000100)
        // y[3] = D (001000)
        // y[4] = E (010000)
        // y[5] = F (100000)

        // 1. Exhaustive testing of all single-hot states with w = 0 and w = 1
        for (i = 0; i < 6; i = i + 1) begin
            for (j = 0; j < 2; j = j + 1) begin
                y = (1 << i);
                w = j[0];
                #10;

                // Compute expected based on FSM specs:
                // Y1 is next-state for B (y[1]).
                // Transitions to B: A(y[0]) with w=1 -> Y1 = y[0] & w
                // Y3 is next-state for D (y[3]).
                // Transitions to D: B(y[1]), C(y[2]), E(y[4]), F(y[5]) with w=0 -> (y[1]|y[2]|y[4]|y[5]) & ~w

                reg exp_Y1, exp_Y3;
                exp_Y1 = (i == 0 && w == 1);
                exp_Y3 = ((i == 1 || i == 2 || i == 4 || i == 5) && (w == 0));

                if (Y1 !== exp_Y1) begin
                    $display("MISMATCH: y=6'b%b, w=%b | Y1 = %b (Expected %b)", y, w, Y1, exp_Y1);
                    errors = errors + 1;
                end
                if (Y3 !== exp_Y3) begin
                    $display("MISMATCH: y=6'b%b, w=%b | Y3 = %b (Expected %b)", y, w, Y3, exp_Y3);
                    errors = errors + 1;
                end
            end
        end

        // 2. Corner Case: Zero-hot (illegal state)
        y = 6'b000000;
        w = 1'b0;
        #10;
        if (Y1 !== 1'b0 || Y3 !== 1'b0) begin
            $display("MISMATCH (Zero-hot): y=6'b000000, w=0 | Y1=%b, Y3=%b (Expected 0,0)", Y1, Y3);
            errors = errors + 1;
        end

        w = 1'b1;
        #10;
        if (Y1 !== 1'b0 || Y3 !== 1'b0) begin
            $display("MISMATCH (Zero-hot): y=6'b000000, w=1 | Y1=%b, Y3=%b (Expected 0,0)", Y1, Y3);
            errors = errors + 1;
        end

        // 3. Corner Case: Multi-hot (illegal states)
        y = 6'b111111;
        w = 1'b0;
        #10;
        // With multi-hot y[1], y[2], y[4], y[5] all active, Y3 should be 1 when w=0.
        // But let's verify against RTL behavior (RTL uses bitwise OR).
        if (Y1 !== (y[0] & w) || Y3 !== ((y[1] | y[2] | y[4] | y[5]) & ~w)) begin
            $display("MISMATCH (Multi-hot): RTL logic divergence detected.");
            errors = errors + 1;
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
